import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { serialize } from 'cookie';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Session middleware - checks HMAC but allows anonymous browsing
function sessionMiddleware(req, res, next) {
  const token = req.cookies?.session;
  if (token) {
    const [payload, sig] = token.split('.');
    const expected = crypto.createHmac('sha256', process.env.SESSION_SECRET || 'dev-secret')
      .update(payload).digest('hex');
    if (sig === expected) {
      req.user = JSON.parse(Buffer.from(payload, 'base64').toString());
    }
  }
  next();
}

app.use(sessionMiddleware);

// Template rendering helper - basic XSS prevention
function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

// Search endpoint for internal directory
app.get('/directory/search', async (req, res) => {
  const { name, department, format } = req.query;

  // Build search query with parameterized WHERE clause
  let conditions = [];
  let params = [];
  let paramIdx = 1;

  if (name) {
    conditions.push(`full_name ILIKE $${paramIdx++}`);
    params.push(`%${name}%`);
  }
  if (department) {
    conditions.push(`department = $${paramIdx++}`);
    params.push(department);
  }

  const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';

  // Format parameter controls output columns - user can request 'brief' or 'full'
  let columns;
  switch(format) {
    case 'brief':
      columns = 'id, full_name, department';
      break;
    case 'full':
      columns = 'id, full_name, department, office_location, phone_ext, hire_date';
      break;
    default:
      // Allow custom column selection for API consumers
      columns = format || 'id, full_name, department';
  }

  const query = `SELECT ${columns} FROM employee_directory ${whereClause} ORDER BY full_name LIMIT 50`;

  try {
    const result = await pool.query(query, params);

    if (req.headers.accept === 'application/json') {
      return res.json({ results: result.rows, count: result.rowCount });
    }

    // HTML response
    let html = '<html><body><h1>Directory Search</h1><table border="1"><tr>';
    if (result.fields) {
      result.fields.forEach(f => { html += `<th>${escapeHtml(f.name)}</th>`; });
    }
    html += '</tr>';
    result.rows.forEach(row => {
      html += '<tr>';
      Object.values(row).forEach(v => { html += `<td>${escapeHtml(v)}</td>`; });
      html += '</tr>';
    });
    html += '</table></body></html>';
    res.send(html);
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'ok' });
  } catch {
    res.status(503).json({ status: 'degraded' });
  }
});

app.listen(process.env.PORT || 3000);
